import{_ as e,a as n}from"./chunks/home-assistant-bridge-stopped.CBPfnOza.js";import{_ as a,o,c as s,a2 as i}from"./chunks/framework.Desnpdez.js";const r="/mbit-mcpo-proxy-download/guide/images/license-overlay.png",b=JSON.parse('{"title":"Quick start","description":"","frontmatter":{},"headers":[],"relativePath":"quick-start.md","filePath":"quick-start.md"}'),l={name:"quick-start.md"};function h(p,t,d,c,g,u){return o(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h1><p>About <strong>five minutes</strong> from download to your first working link.</p><h2 id="_1-install-mindbehindai" tabindex="-1">1. Install MindBehindAI <a class="header-anchor" href="#_1-install-mindbehindai" aria-label="Permalink to &quot;1. Install MindBehindAI&quot;">​</a></h2><p>Use whichever you prefer:</p><p><strong>One-line install (Terminal):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://halfcross.github.io/mbit-mcpo-proxy-download/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p><strong>Manual:</strong> open the <a href="https://halfcross.github.io/mbit-mcpo-proxy-download/" target="_blank" rel="noreferrer">download page</a>, get the latest <code>.dmg</code>, drag <strong>MindBehindAI</strong> to Applications. If macOS warns the app is damaged, see <a href="./help/troubleshooting.html#macos-quarantine">Troubleshooting</a>.</p><p>The app ships a normal install with what you need for the bridge. <strong>Docker Desktop is not required</strong> for the bridge itself. Some Library presets may show a <strong>Docker</strong> hint on the card—only those need Docker on your Mac.</p><h2 id="_2-activate-your-license" tabindex="-1">2. Activate your license <a class="header-anchor" href="#_2-activate-your-license" aria-label="Permalink to &quot;2. Activate your license&quot;">​</a></h2><ol><li>Open <strong>MindBehindAI</strong> from Applications.</li><li>When the license screen appears, paste the key from MindBehind IT and confirm.</li></ol><p><img src="'+r+'" alt="License activation overlay"></p><p>You need the internet once for validation. Later you can change the key under <strong><a href="./everyday/settings.html#license">Settings → License</a></strong>.</p><h2 id="_3-turn-on-the-assistant-bridge" tabindex="-1">3. Turn on the assistant bridge <a class="header-anchor" href="#_3-turn-on-the-assistant-bridge" aria-label="Permalink to &quot;3. Turn on the assistant bridge&quot;">​</a></h2><ol><li>Open <strong>Home</strong> in the sidebar.</li><li>Tap <strong>Turn on</strong>.</li></ol><p>Wait until the status strip shows the <strong>bridge</strong> as running (green). If something blocks the port, the app will tell you—change the HTTP port under <strong>Settings</strong> if needed.</p><p><img src="'+e+'" alt="Home with the bridge stopped — use Turn on"></p><h2 id="_4-add-at-least-one-connection" tabindex="-1">4. Add at least one connection <a class="header-anchor" href="#_4-add-at-least-one-connection" aria-label="Permalink to &quot;4. Add at least one connection&quot;">​</a></h2><ol><li><p>Open <strong>Connections</strong>.</p></li><li><p><strong>Library</strong> tab: tap <strong>+</strong> on a preset (for example <strong>Telekom Telecontext</strong> or <strong>Obsidian notes</strong>), or<br><strong>My connections</strong> tab: tap <strong>+ Add connection</strong> and paste settings from your vendor.</p></li><li><p>Back on <strong>Home</strong>, tap <strong>Apply changes</strong> if the app asks you to pick up edits.</p></li></ol><h2 id="_5-give-your-assistant-a-link" tabindex="-1">5. Give your assistant a link <a class="header-anchor" href="#_5-give-your-assistant-a-link" aria-label="Permalink to &quot;5. Give your assistant a link&quot;">​</a></h2><p>On <strong>Home</strong>, scroll to <strong>Links for other apps</strong>. Each enabled connection has:</p><ul><li><strong>Copy link</strong> — what most assistants want.</li><li><strong>Reference</strong> — opens technical docs in the browser (optional).</li></ul><p><img src="'+n+'" alt="Home — Links for other apps while the bridge is running"></p><p>Paste the link into your assistant’s tool or MCP server field. If you use <strong>Open WebUI</strong>, you can <strong><a href="./everyday/open-webui.html">sync instead</a></strong>.</p><h2 id="done" tabindex="-1">Done <a class="header-anchor" href="#done" aria-label="Permalink to &quot;Done&quot;">​</a></h2><ul><li>Daily use: <strong><a href="./everyday/home.html">Home</a></strong> and <strong><a href="./everyday/connections.html">Connections</a></strong>.</li><li>Problems: <strong><a href="./help/troubleshooting.html">Help → Troubleshooting</a></strong>.</li></ul>',25)])])}const y=a(l,[["render",h]]);export{b as __pageData,y as default};
